  .hide-scrollbar {
    -ms-overflow-style: none;  /* Edge */
    scrollbar-width: none; /* FF */

    /* Chrome/Safari/Opera */
    &::-webkit-scrollbar {
      display: none;
    }
  }

  .hide-on-dark-mode {
    html[data-theme="dark"] & {
      display: none;
    }

    html:not([data-theme]) & {
      @media (prefers-color-scheme: dark) {
        display: none;
      }
    }
  }

  .hide-on-light-mode {
    html[data-theme="light"] & {
      display: none;
    }

    html:not([data-theme]) & {
      @media (prefers-color-scheme: light) {
        display: none;
      }
    }
  }
}

