cat <<'EOF' > /tmp/check_geometry.rb
require "application_system_test_case"

class GeometryCheckTest < ApplicationSystemTestCase
  include ActionView::RecordIdentifier

  test "inspect geometry and styles" do
    card = cards(:layout)
    comment = comments(:layout_overflowing_david)
    sign_in_as(users(:kevin))
    visit card_url(card)

    within "##{dom_id(comment)}" do
      info_empty = page.evaluate_script(<<~JS)
        (() => {
          const commentEl = document.querySelector("##{dom_id(comment)}");
          const reactions = commentEl.querySelector(".reactions");
          const trigger = commentEl.querySelector(".reactions__trigger");
          const img = trigger.querySelector("img");
          return {
            reactionsPos: getComputedStyle(reactions).position,
            reactionsRect: reactions.getBoundingClientRect(),
            triggerRect: trigger.getBoundingClientRect(),
            imgRect: img.getBoundingClientRect(),
            imgNaturalWidth: img.naturalWidth
          };
        })()
      JS
      puts "EMPTY STATE: #{JSON.pretty_generate(info_empty)}"

      find(".reactions__trigger").click
      assert_selector "form.reaction.reaction__form"

      # Wait for 300ms animation to finish
      sleep 0.35

      info_form = page.evaluate_script(<<~JS)
        (() => {
          const commentEl = document.querySelector("##{dom_id(comment)}");
          const reactions = commentEl.querySelector(".reactions");
          const form = commentEl.querySelector(".reaction__form");
          const avatar = form.querySelector(".avatar");
          const input = form.querySelector(".reaction__input");
          const menuBtn = form.querySelector(".reaction__menu-btn");
          const submitBtn = form.querySelector(".reaction__submit-btn");
          const cancelBtn = form.querySelector(".reaction__cancel-btn");
          return {
            activeTag: document.activeElement?.className,
            reactionsPos: getComputedStyle(reactions).position,
            formRect: form.getBoundingClientRect(),
            avatarRect: avatar.getBoundingClientRect(),
            inputRect: input.getBoundingClientRect(),
            menuBtnRect: menuBtn.getBoundingClientRect(),
            submitBtnRect: submitBtn.getBoundingClientRect(),
            submitBtnColor: getComputedStyle(submitBtn).color,
            cancelBtnRect: cancelBtn.getBoundingClientRect(),
            cancelBtnColor: getComputedStyle(cancelBtn).color
          };
        })()
      JS
      puts "FORM STATE: #{JSON.pretty_generate(info_form)}"

      find(".reaction__menu-btn").click
      info_popup = page.evaluate_script(<<~JS)
        (() => {
          const popup = document.querySelector(".reaction__popup");
          const firstEmoji = popup.querySelector(".reaction__emoji-list .btn");
          return {
            popupOpen: popup.open,
            popupRect: popup.getBoundingClientRect(),
            firstEmojiRect: firstEmoji.getBoundingClientRect()
          };
        })()
      JS
      puts "POPUP STATE: #{JSON.pretty_generate(info_popup)}"

      within ".reaction__emoji-list" do
        click_button "Thumbs up"
      end
      find(".reaction__submit-btn").click
      assert_selector ".reaction[title='Kevin']"

      find(".reaction[title='Kevin']").click
      info_reaction = page.evaluate_script(<<~JS)
        (() => {
          const r = document.querySelector("##{dom_id(comment)} .reaction");
          const avatar = r.querySelector(".avatar");
          const span = r.querySelector("span.txt-small");
          const del = r.querySelector(".reaction__delete");
          return {
            classes: r.className,
            padding: getComputedStyle(r).padding,
            rRect: r.getBoundingClientRect(),
            avatarRect: avatar.getBoundingClientRect(),
            spanClasses: span.className,
            delDisplay: getComputedStyle(del).display,
            delRect: del.getBoundingClientRect()
          };
        })()
      JS
      puts "EXPANDED EMOJI REACTION STATE: #{JSON.pretty_generate(info_reaction)}"
    end
  end
end
EOF
